  $mathstatzzjs${"slug": "mathematical-statistics", "title": "Mathematical Statistics", "description": "A proof-aware course in probability-based statistical inference, estimation, testing, asymptotics, Bayesian ideas, and model-based reasoning.", "topics": [{"id": "136be7ca-0e49-4aae-8c80-9e548e7c48e2", "type": "topic", "title": "Statistical models and sampling", "description": "This module establishes statistical models and sampling as the course's first working framework. It supplies the language and representations needed before the path advances to statistics and distributions.", "children": [{"id": "e4e0caf5-12a6-44d4-a6c0-a8d2f3cdb265", "type": "subtopic", "title": "Likelihood", "children": [], "description": "Likelihood is a governing quantity in statistical models and sampling, linking local calculations to system-level behavior and offering a consistency check. It appears before parameter spaces because that next topic assumes this starting point."}, {"id": "03108ec4-c48c-4d8c-a105-17ee176795c0", "type": "subtopic", "title": "Parameter spaces", "children": [], "description": "Parameter spaces gives statistical models and sampling a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After likelihood, parameter spaces supplies what is needed to address identifiability."}, {"id": "082a07fc-05d2-4cf6-b874-579bb907f52f", "type": "subtopic", "title": "Identifiability", "children": [], "description": "Identifiability identifies a specific object, distinction, or relationship within statistical models and sampling. Learners need to recognize and use it before combining this module's ideas in later work. After parameter spaces, identifiability supplies what is needed to address simulation."}, {"id": "4aaeac56-fbda-4a7e-9c75-ad72d1c62015", "type": "subtopic", "title": "Simulation", "children": [], "description": "Simulation identifies a specific object, distinction, or relationship within statistical models and sampling. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, simulation carries the completed idea into statistics and distributions."}]}, {"id": "61e6e8b7-bdfc-4f86-b0f6-892f4156ef32", "type": "topic", "title": "Statistics and distributions", "description": "This module builds directly on statistical models and sampling and develops statistics and distributions. It belongs here because its methods and distinctions are prerequisites for sufficiency and completeness.", "children": [{"id": "c4fe0ebc-9257-4efd-bcf4-3a483751d678", "type": "subtopic", "title": "Transformations", "children": [], "description": "Transformations makes difficult behavior in statistics and distributions tractable while exposing the assumptions and accuracy limits used by later methods. It appears before order statistics because that next topic assumes this starting point."}, {"id": "e9ba55d3-b512-4431-9b68-d10a1b0ab833", "type": "subtopic", "title": "Order statistics", "children": [], "description": "Order statistics identifies a specific object, distinction, or relationship within statistics and distributions. Learners need to recognize and use it before combining this module's ideas in later work. After transformations, order statistics supplies what is needed to address pivotal quantities."}, {"id": "f1a0d338-89b3-4c4e-8a36-8787d7f2c7d5", "type": "subtopic", "title": "Pivotal quantities", "children": [], "description": "Pivotal quantities identifies a specific object, distinction, or relationship within statistics and distributions. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, pivotal quantities carries the completed idea into sufficiency and completeness."}]}, {"id": "fc136daa-d418-4779-a6a0-9f78a678899e", "type": "topic", "title": "Sufficiency and completeness", "description": "This module builds directly on statistics and distributions and develops sufficiency and completeness. It belongs here because its methods and distinctions are prerequisites for point estimation.", "children": [{"id": "2711e543-1fad-4cb5-be37-488cd00c897b", "type": "subtopic", "title": "Factorization theorem", "children": [], "description": "Factorization theorem provides a formal guarantee or inference rule for sufficiency and completeness, allowing later conclusions to be justified rather than inferred from examples alone. It appears before exponential families because that next topic assumes this starting point."}, {"id": "174b387b-8706-4b7b-afa5-2cbc4bc11eee", "type": "subtopic", "title": "Exponential families", "children": [], "description": "Exponential families identifies a specific object, distinction, or relationship within sufficiency and completeness. Learners need to recognize and use it before combining this module's ideas in later work. After factorization theorem, exponential families supplies what is needed to address ancillarity."}, {"id": "49886230-ce8d-4c6a-abf2-9c08c3b321cc", "type": "subtopic", "title": "Ancillarity", "children": [], "description": "Ancillarity identifies a specific object, distinction, or relationship within sufficiency and completeness. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, ancillarity carries the completed idea into point estimation."}]}, {"id": "ee67411d-40f3-472f-bd32-b751a2f55f80", "type": "topic", "title": "Point estimation", "description": "This module builds directly on sufficiency and completeness and develops point estimation. It belongs here because its methods and distinctions are prerequisites for estimator quality.", "children": [{"id": "65707a3f-492c-4d27-a986-bba5bc2a98db", "type": "subtopic", "title": "Method of moments", "children": [], "description": "Method of moments identifies a specific object, distinction, or relationship within point estimation. Learners need to recognize and use it before combining this module's ideas in later work. It appears before maximum likelihood because that next topic assumes this starting point."}, {"id": "458886de-3c40-4fbc-bc6a-4c991caf2e04", "type": "subtopic", "title": "Maximum likelihood", "children": [], "description": "Maximum likelihood is a governing quantity in point estimation, linking local calculations to system-level behavior and offering a consistency check. After method of moments, maximum likelihood supplies what is needed to address equivariance."}, {"id": "3e590f06-4c32-4343-9f39-2bbedce1cfe4", "type": "subtopic", "title": "Equivariance", "children": [], "description": "Equivariance identifies a specific object, distinction, or relationship within point estimation. Learners need to recognize and use it before combining this module's ideas in later work. After maximum likelihood, equivariance supplies what is needed to address computation."}, {"id": "e1fbeb84-459f-4074-95ac-7915ab107f37", "type": "subtopic", "title": "Computation", "children": [], "description": "Computation is an executable part of point estimation; its correctness, cost, and failure modes recur in later problems and implementations. As the final topic in this module, computation carries the completed idea into estimator quality."}]}, {"id": "5084d805-f385-4f11-a6e7-ce73f7a848a1", "type": "topic", "title": "Estimator quality", "description": "This module builds directly on point estimation and develops estimator quality. It belongs here because its methods and distinctions are prerequisites for improved estimation.", "children": [{"id": "98569fae-0924-4a84-87b6-8a7c66595c2d", "type": "subtopic", "title": "Bias", "children": [], "description": "Bias identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. It appears before variance because that next topic assumes this starting point."}, {"id": "dea71f68-830f-4106-b13a-6ffb28d1500e", "type": "subtopic", "title": "Variance", "children": [], "description": "Variance identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. After bias, variance supplies what is needed to address mse."}, {"id": "b4c366e5-2ee0-472e-97da-3b3b093202ce", "type": "subtopic", "title": "MSE", "children": [], "description": "MSE identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. After variance, mse supplies what is needed to address consistency."}, {"id": "65d943e7-af7c-4fcb-bb39-fd2bb32262d9", "type": "subtopic", "title": "Consistency", "children": [], "description": "Consistency identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. After mse, consistency supplies what is needed to address fisher information."}, {"id": "684ad8d7-5532-4b92-b03d-c2c8b06efef8", "type": "subtopic", "title": "Fisher information", "children": [], "description": "Fisher information identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. After consistency, fisher information supplies what is needed to address cramér–rao."}, {"id": "607d983c-7911-47f8-8b7b-ec184f78ce77", "type": "subtopic", "title": "Cramér–Rao", "children": [], "description": "Cramér–Rao identifies a specific object, distinction, or relationship within estimator quality. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, cramér–rao carries the completed idea into improved estimation."}]}, {"id": "07504506-bbdd-498a-aeda-a252afd8bf5c", "type": "topic", "title": "Improved estimation", "description": "This module builds directly on estimator quality and develops improved estimation. It belongs here because its methods and distinctions are prerequisites for confidence sets.", "children": [{"id": "dda6821e-5f06-4556-bd2c-f9c3fc9ed9cc", "type": "subtopic", "title": "Rao–Blackwell", "children": [], "description": "Rao–Blackwell identifies a specific object, distinction, or relationship within improved estimation. Learners need to recognize and use it before combining this module's ideas in later work. It appears before lehmann–scheffé because that next topic assumes this starting point."}, {"id": "908490f5-a6dc-478c-a860-3a56019d19f8", "type": "subtopic", "title": "Lehmann–Scheffé", "children": [], "description": "Lehmann–Scheffé identifies a specific object, distinction, or relationship within improved estimation. Learners need to recognize and use it before combining this module's ideas in later work. After rao–blackwell, lehmann–scheffé supplies what is needed to address decision-theory viewpoint."}, {"id": "a9858070-891c-443b-b5df-8b61c3c065ac", "type": "subtopic", "title": "Decision-theory viewpoint", "children": [], "description": "Decision-theory viewpoint identifies a specific object, distinction, or relationship within improved estimation. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, decision-theory viewpoint carries the completed idea into confidence sets."}]}, {"id": "fec63ba6-71ea-4c75-b6a3-96c952f89280", "type": "topic", "title": "Confidence sets", "description": "This module builds directly on improved estimation and develops confidence sets. It belongs here because its methods and distinctions are prerequisites for hypothesis testing.", "children": [{"id": "0af50566-3a95-4b7c-972d-10aeb76bae82", "type": "subtopic", "title": "Pivots", "children": [], "description": "Pivots identifies a specific object, distinction, or relationship within confidence sets. Learners need to recognize and use it before combining this module's ideas in later work. It appears before exact vs approximate intervals because that next topic assumes this starting point."}, {"id": "24ef45f2-2f1f-4352-a38e-93b752a544fa", "type": "subtopic", "title": "Exact vs approximate intervals", "children": [], "description": "Exact vs approximate intervals identifies a specific object, distinction, or relationship within confidence sets. Learners need to recognize and use it before combining this module's ideas in later work. After pivots, exact vs approximate intervals supplies what is needed to address bootstrap concepts."}, {"id": "3b72de43-5311-4162-a3eb-3e4a6670a8fe", "type": "subtopic", "title": "Bootstrap concepts", "children": [], "description": "Bootstrap concepts identifies a specific object, distinction, or relationship within confidence sets. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, bootstrap concepts carries the completed idea into hypothesis testing."}]}, {"id": "604676eb-2855-4171-84ea-0c20ac32542f", "type": "topic", "title": "Hypothesis testing", "description": "This module builds directly on confidence sets and develops hypothesis testing. It belongs here because its methods and distinctions are prerequisites for multiple and nonparametric testing.", "children": [{"id": "b2af14e2-5d61-47b1-93db-08dde79cc59f", "type": "subtopic", "title": "Neyman–Pearson", "children": [], "description": "Neyman–Pearson identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module's ideas in later work. It appears before likelihood-ratio tests because that next topic assumes this starting point."}, {"id": "bc9afd75-8af8-4eb2-b2e0-1a8600f26511", "type": "subtopic", "title": "Likelihood-ratio tests", "children": [], "description": "Likelihood-ratio tests is a governing quantity in hypothesis testing, linking local calculations to system-level behavior and offering a consistency check. After neyman–pearson, likelihood-ratio tests supplies what is needed to address p-values."}, {"id": "c37e5f0d-cd60-4eda-80d9-d5d5a17eefa5", "type": "subtopic", "title": "P-values", "children": [], "description": "P-values identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module's ideas in later work. After likelihood-ratio tests, p-values supplies what is needed to address power."}, {"id": "8f1b19d1-cb71-4993-9ae3-db209b8b1c51", "type": "subtopic", "title": "Power", "children": [], "description": "Power identifies a specific object, distinction, or relationship within hypothesis testing. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, power carries the completed idea into multiple and nonparametric testing."}]}, {"id": "4cef0087-5ab7-49c8-bfc4-dd870b244d94", "type": "topic", "title": "Multiple and nonparametric testing", "description": "This module builds directly on hypothesis testing and develops multiple and nonparametric testing. It belongs here because its methods and distinctions are prerequisites for bayesian inference.", "children": [{"id": "73ce038e-1b15-4914-bd60-031816297688", "type": "subtopic", "title": "Rank tests", "children": [], "description": "Rank tests identifies a specific object, distinction, or relationship within multiple and nonparametric testing. Learners need to recognize and use it before combining this module's ideas in later work. It appears before permutation because that next topic assumes this starting point."}, {"id": "0c3c7ff6-3a28-43c7-ae06-518a7a1aa1cc", "type": "subtopic", "title": "Permutation", "children": [], "description": "Permutation identifies a specific object, distinction, or relationship within multiple and nonparametric testing. Learners need to recognize and use it before combining this module's ideas in later work. After rank tests, permutation supplies what is needed to address multiplicity."}, {"id": "af947b9b-967c-4088-a2aa-6582c00c8550", "type": "subtopic", "title": "Multiplicity", "children": [], "description": "Multiplicity identifies a specific object, distinction, or relationship within multiple and nonparametric testing. Learners need to recognize and use it before combining this module's ideas in later work. After permutation, multiplicity supplies what is needed to address robustness."}, {"id": "3b63270d-1b5c-45ac-b75c-cd354ae01fa4", "type": "subtopic", "title": "Robustness", "children": [], "description": "Robustness identifies a specific object, distinction, or relationship within multiple and nonparametric testing. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, robustness carries the completed idea into bayesian inference."}]}, {"id": "f14d41d9-a4fe-450a-970e-99a2ad650f62", "type": "topic", "title": "Bayesian inference", "description": "This module builds directly on multiple and nonparametric testing and develops bayesian inference. It belongs here because its methods and distinctions are prerequisites for asymptotic theory.", "children": [{"id": "55261c69-47c9-4de3-a960-57a14d862582", "type": "subtopic", "title": "Priors", "children": [], "description": "Priors identifies a specific object, distinction, or relationship within bayesian inference. Learners need to recognize and use it before combining this module's ideas in later work. It appears before posteriors because that next topic assumes this starting point."}, {"id": "9004f32f-1ba1-4ab0-93fa-274124e7d7e0", "type": "subtopic", "title": "Posteriors", "children": [], "description": "Posteriors identifies a specific object, distinction, or relationship within bayesian inference. Learners need to recognize and use it before combining this module's ideas in later work. After priors, posteriors supplies what is needed to address conjugacy."}, {"id": "4a5c86f1-3fc4-42b5-b0a2-4f6969382a2a", "type": "subtopic", "title": "Conjugacy", "children": [], "description": "Conjugacy identifies a specific object, distinction, or relationship within bayesian inference. Learners need to recognize and use it before combining this module's ideas in later work. After posteriors, conjugacy supplies what is needed to address credible sets."}, {"id": "9660da4d-0b60-4e03-af5a-ede1453d6df3", "type": "subtopic", "title": "Credible sets", "children": [], "description": "Credible sets identifies a specific object, distinction, or relationship within bayesian inference. Learners need to recognize and use it before combining this module's ideas in later work. After conjugacy, credible sets supplies what is needed to address predictive checks."}, {"id": "71893030-28b6-4159-ac2f-e4fd226ce997", "type": "subtopic", "title": "Predictive checks", "children": [], "description": "Predictive checks identifies a specific object, distinction, or relationship within bayesian inference. Learners need to recognize and use it before combining this module's ideas in later work. As the final topic in this module, predictive checks carries the completed idea into asymptotic theory."}]}, {"id": "36c9f819-4996-488a-a72f-2e0427119c09", "type": "topic", "title": "Asymptotic theory", "description": "This module builds directly on bayesian inference and develops asymptotic theory. It belongs here because its methods and distinctions are prerequisites for linear-model synthesis.", "children": [{"id": "cbbc921c-dea0-4e5a-98e4-009bd0dfdd6e", "type": "subtopic", "title": "LLN/CLT in inference", "children": [], "description": "LLN/CLT in inference identifies a specific object, distinction, or relationship within asymptotic theory. Learners need to recognize and use it before combining this module's ideas in later work. It appears before delta method because that next topic assumes this starting point."}, {"id": "c215b6a2-2f94-43fb-8468-c31e6a032c18", "type": "subtopic", "title": "Delta method", "children": [], "description": "Delta method identifies a specific object, distinction, or relationship within asymptotic theory. Learners need to recognize and use it before combining this module's ideas in later work. After lln/clt in inference, delta method supplies what is needed to address asymptotic normality of mle."}, {"id": "9dc81bd2-916b-4d91-866a-990344f12353", "type": "subtopic", "title": "Asymptotic normality of MLE", "children": [], "description": "Asymptotic normality of MLE makes difficult behavior in asymptotic theory tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, asymptotic normality of mle carries the completed idea into linear-model synthesis."}]}, {"id": "0d3bf9bd-fc91-4797-a155-a8e91d5016b2", "type": "topic", "title": "Linear-model synthesis", "description": "This culminating module draws on asymptotic theory and develops linear-model synthesis. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.", "children": [{"id": "977e2033-7fa2-40b2-9f99-6672c489f5f4", "type": "subtopic", "title": "Least squares", "children": [], "description": "Least squares identifies a specific object, distinction, or relationship within linear-model synthesis. Learners need to recognize and use it before combining this module's ideas in later work. It appears before normal theory because that next topic assumes this starting point."}, {"id": "74a82a91-cf24-47ca-a0ae-02bfa9fdf939", "type": "subtopic", "title": "Normal theory", "children": [], "description": "Normal theory identifies a specific object, distinction, or relationship within linear-model synthesis. Learners need to recognize and use it before combining this module's ideas in later work. After least squares, normal theory supplies what is needed to address diagnostics."}, {"id": "f7996ba4-f2f9-4e8a-86ee-b9bc3e39316c", "type": "subtopic", "title": "Diagnostics", "children": [], "description": "Diagnostics makes the validity limits of linear-model synthesis explicit, showing when an otherwise correct method or system can become unreliable. After normal theory, diagnostics supplies what is needed to address model misspecification."}, {"id": "1712f06c-bca2-4520-8aea-8478ffb87cd5", "type": "subtopic", "title": "Model misspecification", "children": [], "description": "Model misspecification gives linear-model synthesis a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final course topic, model misspecification requires ideas from the complete path to be integrated and transferred."}]}], "dbBacked": true}$mathstatzzjs$::jsonb,
